const b = $json.body;
const keys = (o, expected) => o && typeof o === 'object' && !Array.isArray(o) && Object.keys(o).sort().join(',') === expected.sort().join(',');
if (!keys(b, ['schema_version','mission_id','workflow','input']) || b.schema_version !== 1 || !/^[a-f0-9]{32}$/.test(b.mission_id) || b.workflow !== 'inspect_fixture' || !keys(b.input, ['application']) || typeof b.input.application !== 'string' || !/^[a-z][a-z0-9-]{0,39}$/.test(b.input.application)) throw new Error('Invalid IGRIS fixture contract');
return [{json: {schema_version:1, mission_id:b.mission_id, workflow:'inspect_fixture', status:'completed', output:{summary:'Simulated workflow: inspected fixture ' + b.input.application}}}];
